import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
/** Independent inverse of the NPC accepted consumers; excludes the splice generator. */
public final class SourceDollNpcDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",C=P+"NativeSourceControlledDisplay",CTX=P+"NativeAreaMaterialAction$Context",D=P+"NativeSourceNpcDamageDisplay",N=P+"NativeSourceDollNpc",EXTRA="L"+P+"NativeMagicDollEffects$AttackProc;L"+P+"SourceNpcPhysicalStats;";
 static void need(boolean b,String why){if(!b)throw new AssertionError(why);}
 static void args(MethodNode m,MethodInsnNode call,int first,int second){var b=FreezeAcceptedMethods.prev(call);var a=FreezeAcceptedMethods.prev(b);need(a instanceof VarInsnNode x&&x.getOpcode()==ALOAD&&x.var==first&&b instanceof VarInsnNode y&&y.getOpcode()==ALOAD&&y.var==second,"exact original argument identities");m.instructions.remove(a);m.instructions.remove(b);call.desc=call.desc.replace(EXTRA+")",")");}
 static void same(ClassNode a,MethodNode x,ClassNode b,MethodNode y){var before=FreezeSourceTargetDelta.body(a,x,x.name,x.access);var after=FreezeSourceTargetDelta.body(b,y,x.name,x.access);need(Arrays.equals(before,after),"original inverse "+a.name+'.'+x.name+" via "+y.name+" bytes="+before.length+"/"+after.length+" mismatch="+Arrays.mismatch(before,after)+" locals="+x.maxLocals+"/"+y.maxLocals+" stack="+x.maxStack+"/"+y.maxStack);}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){var names=List.of(PC,C,CTX,D);var entries=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){entries.add(e.getName());var n=jar.getJarEntry(e.getName());need(n!=null,"no deletions");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(n).readAllBytes()))changed.add(e.getName());}need(changed.equals(names.stream().map(x->x+".class").collect(java.util.stream.Collectors.toSet())),"four exact changed classes "+changed);int count=0,natural=0,controlled=0,bridge=0,calc=0,commit=0,accepted=0;
  for(var name:names){var old=FreezeSourceTargetDelta.read(base,name);var now=FreezeSourceTargetDelta.read(jar,name);need(now.fields.size()==old.fields.size()+(name.equals(CTX)?1:0),"single context field");for(int i=0;i<old.fields.size();i++){var x=old.fields.get(i);var y=now.fields.get(i);need(x.name.equals(y.name)&&x.desc.equals(y.desc)&&x.access==y.access&&Objects.equals(x.value,y.value),"original fields");}if(name.equals(CTX)){var f=now.fields.get(now.fields.size()-1);need(f.name.equals("nativeSourceDollNpcScope")&&f.desc.equals("Ljava/lang/Object;")&&f.access==ACC_VOLATILE,"synchronous scope slot");}need(now.methods.size()==old.methods.size()+(name.equals(C)?1:0),"only controlled sibling");
   for(var before:old.methods){var after=now.methods.stream().filter(x->x.name.equals(before.name)&&x.desc.equals(before.desc)).findFirst().orElseThrow();for(var node:after.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(N)){
    if(Set.of("physicalQuest","physicalTime").contains(call.name)){need(name.equals(PC)&&before.name.equals("nativeSourceControlledOriginal_attack"),"natural physical root");args(after,call,171,24);call.owner=D;natural++;}
    else if(call.name.equals("controlled")){need(name.equals(PC)&&before.name.equals("nativeSourceControlledOriginal_attack"),"controlled physical root");args(after,call,171,24);call.owner=C;call.name="physical";controlled++;}
    else if(call.name.equals("submitted")){need(name.equals(PC)&&before.name.equals("nativeSourceControlledOriginal_attack"),"old postsubmission bridge");call.owner=P+"NativeSourceDollAccepted";bridge++;}
    else if(call.name.equals("skillDamage")){need(name.equals(PC)&&before.name.equals("nativeSourceDollOrderedAttackProcs"),"only Source sibling calculation");call.owner=PC;call.name="nativeMagicDollTriggeredSkillDamage";call.desc="("+call.desc.substring(("(L"+PC+";").length());call.setOpcode(INVOKEVIRTUAL);calc++;}
    else if(call.name.equals("commit")){need(name.equals(PC)&&before.name.equals("nativeSourceDollOrderedAttackProcs"),"only typed Source commits");call.owner=P+"NativeSourceDollCommit";commit++;}
    else if(call.name.equals("acceptedNatural")){need(name.equals(D)&&Set.of("questDamage","timeDamage").contains(before.name),"original actual HP receipt only");var load=FreezeAcceptedMethods.prev(call);need(load instanceof VarInsnNode v&&v.var==7&&v.getOpcode()==ALOAD,"actual sealed receipt");need(FreezeAcceptedMethods.next(call).getOpcode()==ARETURN,"after HP result before publisher");var previous=FreezeAcceptedMethods.prev(load);need(previous.getOpcode()==MONITOREXIT,"callback immediately after Hub monitor exits with original result still stacked");after.instructions.remove(load);after.instructions.remove(call);accepted++;}else throw new AssertionError(call.name);
   }same(old,before,now,after);count++;
   if(name.equals(C)&&before.name.equals("physical")){var sibling=now.methods.stream().filter(x->x.name.equals("nativeSourceDollPhysical")).findFirst().orElseThrow();need(sibling.desc.equals(before.desc.replace(")",EXTRA+")")),"same original inputs plus frozen proc/stats");int hooks=0;for(var node:sibling.instructions.toArray())if(node instanceof MethodInsnNode call&&call.owner.equals(N)&&call.name.equals("controlledAccepted")){args(sibling,call,9,10);call.owner=C;call.name="publish";hooks++;}need(hooks==1,"exact accepted positive HP publication guard");for(var node:sibling.instructions){if(node instanceof VarInsnNode v&&v.var>=11)v.var-=2;else if(node instanceof IincInsnNode i&&i.var>=11)i.var-=2;}sibling.desc=before.desc;if(sibling.signature!=null){need(sibling.signature.equals(before.signature.replace(")",EXTRA+")")),"same generic signature plus proc/stats");sibling.signature=sibling.signature.replace(EXTRA+")",")");}sibling.maxLocals-=2;same(old,before,now,sibling);}
  }}need(natural==2&&controlled==1&&bridge==3&&calc==1&&commit==2&&accepted==4,"exact consumer counts");int fresh=0;
  for(var e:Collections.list(jar.entries()))if(!entries.contains(e.getName())){need(Set.of(N+".class",N+"$Scope.class").contains(e.getName()),"two bounded synchronous helper classes");fresh++;var c=FreezeSourceTargetDelta.read(jar,e.getName().replace(".class",""));for(var f:c.fields)need((f.access&ACC_STATIC)==0||f.value instanceof String,"no actor registry");for(var m:c.methods)for(var node:m.instructions){if(node instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(!t.desc.contains("Thread")&&!t.desc.contains("Executor"),"no new worker/TLS");if(node instanceof MethodInsnNode call){need(!call.owner.startsWith("java/sql/")&&!call.owner.startsWith("java/nio/file/")&&!call.owner.contains("Repository")&&!call.owner.contains("GameStateStore"),"no persistence authority");need(!(call.owner.equals(P+"NativeMagicDollEffects")&&Set.of("attack","defense").contains(call.name)),"no rerolled proc RNG");}if(node instanceof FieldInsnNode f&&f.getOpcode()==PUTFIELD)need(!f.owner.endsWith("$Plan")||!f.desc.contains("Scope"),"no scope in delayed plan");}}
  need(fresh==2,"two new classes");System.out.println("PASS independent NPC-doll inverse: "+count+" original methods, actual HP receipt after Hub unlock before publisher, original controlled physical body, proc RNG retained, no workers/TLS/persistence");
 }}
}
